scripts.iterative_modulo:
def solve(inputs: dict) -> float:
    s = inputs['SEED']
    A = inputs['A']
    B = inputs['B']
    M = inputs['M']
    K = inputs['K']

    for _ in range(int(K)):
        s = (A * s + B) % M

    return float(s)

scripts.modular_exp:
def solve(inputs: dict) -> float:
    base = inputs['BASE']
    exp = inputs['EXP']
    mod = inputs['MOD']

    result = pow(base, exp, mod)
    return float(result)

